// The hand-written PTX of the fast multi-token expert kernels (C1138, GGML_CUDA_MTOK_IQ_FAST=2): ptx/mtok-<type>.ptx,
// generated by ptx/gen_mtok_<type>.py, is the whole kernel of mmvq-pascal-mtok-<type>-fast.cu written as PTX for the
// products Qwen3.8-Flash-Next's verify pass makes: the fused gate/up launch with SWIGLU, rows of 2,560 weights (10
// super-blocks, 2 lanes a row), groups of up to 2, 4 or 8 members (three entry points), no shared expert, no biases.
// Types: IQ2_XXS (code row 28r1), IQ2_S (28r2), IQ2_XS (28r3), IQ1_M (28r4). The build packs each with its compute 6.1 SASS into a
// fatbin (CMakeLists.txt) that this file loads once per device and type with the driver API and launches on ggml's
// stream. Every other product of the fast kernels runs their CUDA C versions.

#include "mmvq-pascal-mtok-iq.cuh"

#include <cstddef>
#include <mutex>

#if !defined(GGML_USE_HIP) && !defined(GGML_USE_MUSA) && !defined(GGML_CUDA_NO_PTX_KERNELS)

#include <cuda.h>

extern const unsigned char ggml_cuda_ptx_mtok_iq2_xxs[];
extern const unsigned char ggml_cuda_ptx_mtok_iq2_s[];
extern const unsigned char ggml_cuda_ptx_mtok_iq2_xs[];
extern const unsigned char ggml_cuda_ptx_mtok_iq1_m[];

// The byte offsets the PTX reads its parameters at (gen_mtok_iq2_xxs.py, shared by every type's generator): the structs
// must not move.
static_assert(sizeof(mtok_iq::args) == 168, "mtok_iq::args: the PTX's parameter is 168 bytes");
static_assert(offsetof(mtok_iq::args, vx) == 0 && offsetof(mtok_iq::args, vy) == 8 && offsetof(mtok_iq::args, ids) == 16 &&
              offsetof(mtok_iq::args, dst) == 24, "mtok_iq::args pointers");
static_assert(offsetof(mtok_iq::args, nrows) == 32 && offsetof(mtok_iq::args, row_bytes) == 36 &&
              offsetof(mtok_iq::args, lpr_log2) == 40 && offsetof(mtok_iq::args, niter) == 44 &&
              offsetof(mtok_iq::args, nrowblocks) == 48 && offsetof(mtok_iq::args, rb) == 52 &&
              offsetof(mtok_iq::args, gcap) == 56 && offsetof(mtok_iq::args, ncols) == 60 &&
              offsetof(mtok_iq::args, nslots) == 64 && offsetof(mtok_iq::args, ids_stride) == 68 &&
              offsetof(mtok_iq::args, nchunk) == 72 && offsetof(mtok_iq::args, act_tok) == 76, "mtok_iq::args ints");
static_assert(offsetof(mtok_iq::args, nchannels_y) == 80 && offsetof(mtok_iq::args, sample_ratio) == 92,
              "mtok_iq::args fastdiv values");
static_assert(offsetof(mtok_iq::args, channel_bytes_x) == 104 && offsetof(mtok_iq::args, sample_bytes_x) == 112 &&
              offsetof(mtok_iq::args, channel_bytes_y) == 120 && offsetof(mtok_iq::args, sample_bytes_y) == 128 &&
              offsetof(mtok_iq::args, col_bytes_y) == 136 && offsetof(mtok_iq::args, stride_channel_dst) == 144 &&
              offsetof(mtok_iq::args, stride_sample_dst) == 152 && offsetof(mtok_iq::args, stride_col_dst) == 160,
              "mtok_iq::args strides");
static_assert(sizeof(ggml_cuda_mm_fusion_args_device) == 80, "fusion args: the PTX's parameter is 80 bytes");
static_assert(offsetof(ggml_cuda_mm_fusion_args_device, gate) == 8, "fusion args: gate");
static_assert(sizeof(ggml_glu_op) == 4 && GGML_GLU_OP_SWIGLU == 2, "fusion args: the PTX computes SWIGLU only");

// The PTX kernels: per type a fatbin and its three entry points (groups of up to 2, 4, 8 members).
struct ptx_kernel {
    ggml_type             type;
    const char          * name;
    const unsigned char * fatbin;
    const char          * fn[3];
};
static const ptx_kernel k_ptx_kernels[] = {
    { GGML_TYPE_IQ2_XXS, "mtok-iq2_xxs", ggml_cuda_ptx_mtok_iq2_xxs,
      { "mtok_iq2xxs_fast_ptx_ntm2", "mtok_iq2xxs_fast_ptx_ntm4", "mtok_iq2xxs_fast_ptx_ntm8" } },
    { GGML_TYPE_IQ2_S,   "mtok-iq2_s",   ggml_cuda_ptx_mtok_iq2_s,
      { "mtok_iq2s_fast_ptx_ntm2",   "mtok_iq2s_fast_ptx_ntm4",   "mtok_iq2s_fast_ptx_ntm8" } },
    { GGML_TYPE_IQ2_XS,  "mtok-iq2_xs",  ggml_cuda_ptx_mtok_iq2_xs,
      { "mtok_iq2xs_fast_ptx_ntm2",  "mtok_iq2xs_fast_ptx_ntm4",  "mtok_iq2xs_fast_ptx_ntm8" } },
    { GGML_TYPE_IQ1_M,   "mtok-iq1_m",   ggml_cuda_ptx_mtok_iq1_m,
      { "mtok_iq1m_fast_ptx_ntm2",   "mtok_iq1m_fast_ptx_ntm4",   "mtok_iq1m_fast_ptx_ntm8" } },
};
static constexpr int N_PTX_KERNELS = (int) (sizeof(k_ptx_kernels) / sizeof(k_ptx_kernels[0]));

struct ptx_module {
    bool       tried = false;
    CUmodule   mod   = nullptr;
    CUfunction fn[3] = {};
};

static ptx_module g_mods[N_PTX_KERNELS][GGML_CUDA_MAX_DEVICES];
static std::mutex g_mutex;

// kernel ki's module on the device, loaded on first use; nullptr if it could not be (the caller then runs the C version)
static const ptx_module * module_for(const int ki, const int device) {
    std::lock_guard<std::mutex> lock(g_mutex);
    const ptx_kernel & k = k_ptx_kernels[ki];
    ptx_module       & m = g_mods[ki][device];
    if (!m.tried) {
        m.tried = true;
        CUmodule mod = nullptr;
        if (cuModuleLoadData(&mod, k.fatbin) != CUDA_SUCCESS) {
            GGML_LOG_WARN("%s: the PTX kernel %s does not load on device %d; GGML_CUDA_MTOK_IQ_FAST=2 runs the CUDA C version\n",
                          __func__, k.name, device);
            return nullptr;
        }
        for (int i = 0; i < 3; ++i) {
            if (cuModuleGetFunction(&m.fn[i], mod, k.fn[i]) != CUDA_SUCCESS) {
                GGML_LOG_WARN("%s: no function %s in the PTX kernel %s\n", __func__, k.fn[i], k.name);
                cuModuleUnload(mod);
                return nullptr;
            }
        }
        m.mod = mod;
    }
    return m.mod ? &m : nullptr;
}

// Whether the PTX takes the product (and then launches it): a type with a PTX kernel, the fused gate/up launch with
// SWIGLU, 10 super-blocks a row, no shared expert, no biases or scales.
bool ggml_cuda_mtok_iq_ptx_launch(const ggml_type type, const mtok_iq::args & p,
                                  const ggml_cuda_mm_fusion_args_device & fusion, const dim3 grid, const int smem,
                                  const bool gate, const int ntm, cudaStream_t stream) {
    int ki = 0;
    while (ki < N_PTX_KERNELS && k_ptx_kernels[ki].type != type) {
        ki++;
    }
    if (ki == N_PTX_KERNELS || !gate || fusion.shared_up || fusion.x_bias || fusion.gate_bias || fusion.x_scale ||
            fusion.gate_scale || fusion.glu_op != GGML_GLU_OP_SWIGLU || p.nchunk != 10 || p.niter != 5 ||
            p.lpr_log2 != 1) {
        return false;
    }
    const ptx_module * m = module_for(ki, ggml_cuda_get_device());
    if (m == nullptr) {
        return false;
    }
    CUfunction fn = m->fn[ntm <= 2 ? 0 : ntm <= 4 ? 1 : 2];
    mtok_iq::args                   pp = p;
    ggml_cuda_mm_fusion_args_device ff = fusion;
    void * params[2] = { &pp, &ff };
    CU_CHECK(cuLaunchKernel(fn, grid.x, grid.y, grid.z, WARP_SIZE, MMVQP_MTOK_IQ_NWARPS, 1, (unsigned) smem, (CUstream) stream,
                            params, nullptr));
    return true;
}

#else

bool ggml_cuda_mtok_iq_ptx_launch(const ggml_type, const mtok_iq::args &, const ggml_cuda_mm_fusion_args_device &,
                                  const dim3, const int, const bool, const int, cudaStream_t) {
    return false;
}

#endif
